from pydantic import BaseModel, Field

class Citation(BaseModel):
    """A reference found within a paper."""
    title: str | None = Field(description="The title of the referenced paper")

class Paper(BaseModel):
    """A paper extracted from the collection, identified by its title and its references."""
    title: str | None = Field(description="The title of the current paper")
    references: list[Citation] = Field(description="List of other papers cited by this paper; the downstream agent filters for those within the collection")

class Parse(BaseModel):
    papers: list[Paper]
